# Terraform: Refactor Dev/Prod Blocks into `for_each` Module

## Strategy

Replace duplicated `resource "aws_eks_cluster" "dev"` / `resource "aws_eks_cluster" "prod"` blocks with a single module instantiated via `for_each`, migrating state with zero-diff using `moved` blocks or `terraform state mv`.

---

## Module Structure

### `modules/app_stack/main.tf`
Consolidate all resources (EKS, S3, RDS, IAM, ALB/CloudFront, Secrets).

```hcl
# modules/app_stack/main.tf

resource "aws_eks_cluster" "this" {
  name            = "${var.environment}-app-cluster"
  role_arn        = aws_iam_role.eks_cluster.arn
  version         = var.kubernetes_version

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]
}

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${var.environment}-app-ng"
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = var.subnet_ids

  scaling_config {
    desired_size = var.node_group_size.desired
    max_size     = var.node_group_size.max
    min_size     = var.node_group_size.min
  }

  instance_types = [var.node_instance_type]
}

resource "aws_s3_bucket" "app_assets" {
  bucket = "${var.environment}-app-assets-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.enable_s3_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    status   = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    destination {
      bucket       = "arn:aws:s3:::${var.environment}-app-assets-replica-${data.aws_caller_identity.current.account_id}"
      storage_class = "STANDARD"
    }
  }
}

resource "aws_db_instance" "postgres" {
  identifier             = "${var.environment}-app-db"
  engine                 = "postgres"
  engine_version         = var.postgres_version
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  storage_encrypted      = true

  multi_az               = var.db_multi_az
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  db_name  = var.db_name
  username = var.db_username
  password = random_password.db_password.result

  backup_retention_period = var.db_backup_retention_days
  deletion_protection     = var.db_deletion_protection
  publicly_accessible     = false

  skip_final_snapshot = var.environment == "dev" ? true : false
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.environment}/app/db-connection"
  recovery_window_in_days = var.secret_recovery_window
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    database = aws_db_instance.postgres.db_name
    username = aws_db_instance.postgres.username
    password = random_password.db_password.result
  })
}

resource "aws_iam_user" "service_account" {
  name = "${var.environment}-app-svc"
}

resource "aws_iam_access_key" "service_account" {
  count = var.create_iam_access_key ? 1 : 0
  user  = aws_iam_user.service_account.name
}

resource "aws_iam_role" "service_account" {
  name = "${var.environment}-app-svc-role"

  assume_role_policy = var.environment == "prod" ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${var.oidc_provider_url}"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${var.oidc_provider_url}:sub" = "system:serviceaccount:default:app"
          }
        }
      }
    ]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.service_account.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${var.environment}-app-svc-policy"
  role   = aws_iam_role.service_account.id
  policy = var.service_account_policy
}

# ALB for dev, CloudFront for prod
resource "aws_lb" "internal" {
  count           = var.enable_internal_alb ? 1 : 0
  name            = "${var.environment}-app-alb"
  internal        = true
  load_balancer_type = "application"
  subnets         = var.subnet_ids
}

resource "aws_lb_listener" "https" {
  count           = var.enable_internal_alb ? 1 : 0
  load_balancer_arn = aws_lb.internal[0].arn
  port            = 443
  protocol        = "HTTPS"
  ssl_certificate_arn = var.certificate_arn
  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
}

resource "aws_cloudfront_distribution" "app" {
  count = var.enable_cloudfront ? 1 : 0

  origin {
    domain_name = var.cloudfront_origin_domain
    origin_id   = "app-origin"
  }

  enabled = true
  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "app-origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  viewer_certificate {
    cloudfront_default_certificate = var.use_cloudfront_default_cert
    acm_certificate_arn            = var.use_cloudfront_default_cert ? null : var.certificate_arn
    ssl_support_method             = var.use_cloudfront_default_cert ? null : "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

# IAM roles for cluster/node
resource "aws_iam_role" "eks_cluster" {
  name = "${var.environment}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role" "eks_node" {
  name = "${var.environment}-eks-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

# S3 replication role (prod only)
resource "aws_iam_role" "s3_replication" {
  count = var.enable_s3_replication ? 1 : 0
  name  = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

# Supporting resources
resource "aws_db_subnet_group" "this" {
  name       = "${var.environment}-db-subnet"
  subnet_ids = var.db_subnet_ids
}

resource "aws_security_group" "rds" {
  name   = "${var.environment}-rds-sg"
  vpc_id = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.rds_allowed_cidr_blocks
  }
}

resource "aws_lb_target_group" "app" {
  count    = var.enable_internal_alb ? 1 : 0
  name     = "${var.environment}-app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id
}

data "aws_caller_identity" "current" {}
```

