```

---

## Root Configuration Refactor

### `main.tf` (before refactor — reference)

```hcl
# BEFORE: Duplicated blocks

resource "aws_eks_cluster" "dev" {
  name    = "dev-app-cluster"
  role_arn = aws_iam_role.eks_cluster_dev.arn
  # ... dev-specific config
}

resource "aws_eks_cluster" "prod" {
  name    = "prod-app-cluster"
  role_arn = aws_iam_role.eks_cluster_prod.arn
  # ... prod-specific config (more nodes, larger instance types)
}

# Similar duplication for S3, RDS, IAM, ALB/CloudFront...
```

### `main.tf` (after refactor)

```hcl
# AFTER: Single module with for_each

module "app_stack" {
  for_each = {
    dev = {
      node_instance_type = "t3.medium"
      node_group_size = {
        desired = 2
        max     = 3
        min     = 2
      }
      db_instance_class       = "db.t3.micro"
      db_multi_az             = false
      db_deletion_protection  = false
      enable_s3_replication   = false
      create_iam_access_key   = true
      enable_internal_alb     = true
      enable_cloudfront       = false
      rds_allowed_cidr_blocks = ["10.0.0.0/8"]
    }
    prod = {
      node_instance_type = "t3.large"
      node_group_size = {
        desired = 4
        max     = 8
        min     = 4
      }
      db_instance_class       = "db.t3.medium"
      db_multi_az             = true
      db_deletion_protection  = true
      enable_s3_replication   = true
      create_iam_access_key   = false
      enable_internal_alb     = false
      enable_cloudfront       = true
      rds_allowed_cidr_blocks = ["10.0.0.0/8"]
    }
  }

  source      = "./modules/app_stack"
  environment = each.key

  vpc_id           = var.vpc_id
  subnet_ids       = var.subnet_ids
  db_subnet_ids    = var.db_subnet_ids
  oidc_provider_url = var.oidc_provider_url

  certificate_arn            = var.certificate_arn
  cloudfront_origin_domain   = var.cloudfront_origin_domain
  use_cloudfront_default_cert = var.use_cloudfront_default_cert

  service_account_policy = jsonencode(
    each.key == "prod" ? local.prod_service_account_policy : local.dev_service_account_policy
  )

  node_instance_type       = each.value.node_instance_type
  node_group_size          = each.value.node_group_size
  db_instance_class        = each.value.db_instance_class
  db_multi_az              = each.value.db_multi_az
  db_deletion_protection   = each.value.db_deletion_protection
  enable_s3_replication    = each.value.enable_s3_replication
  create_iam_access_key    = each.value.create_iam_access_key
  enable_internal_alb      = each.value.enable_internal_alb
  enable_cloudfront        = each.value.enable_cloudfront
  rds_allowed_cidr_blocks  = each.value.rds_allowed_cidr_blocks
}

locals {
  dev_service_account_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:ListBucket"]
        Resource = ["${module.app_stack["dev"].s3_bucket_arn}", "${module.app_stack["dev"].s3_bucket_arn}/*"]
      }
    ]
  }

  prod_service_account_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${module.app_stack["prod"].s3_bucket_arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = module.app_stack["prod"].db_secret_arn
      }
    ]
  }
}
```

